#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

const int64 MOD = 1000000007;

int64 modPow(int64 base, int64 exp) {
    int64 result = 1;
    base %= MOD;
    while (exp > 0) {
        if (exp & 1) result = result * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n;
    int k;
    cin >> n >> k;

    vector<pair<int64, int>> factors;

    auto extract = [&](int64 p) {
        if (n % p != 0) return;
        int exponent = 0;
        while (n % p == 0) {
            n /= p;
            ++exponent;
        }
        factors.push_back({p, exponent});
    };

    extract(2);
    extract(3);

    for (int64 p = 5; p <= n / p; p += 6) {
        extract(p);
        extract(p + 2);
    }

    if (n > 1) factors.push_back({n, 1});

    int64 inverse[51];
    for (int i = 1; i <= 50; ++i) {
        inverse[i] = modPow(i, MOD - 2);
    }

    int64 answer = 1;

    for (auto [prime, exponent] : factors) {
        vector<int64> probability(exponent + 1, 0);
        probability[exponent] = 1;

        for (int step = 0; step < k; ++step) {
            vector<int64> next(exponent + 1, 0);
            int64 suffix = 0;

            for (int e = exponent; e >= 0; --e) {
                suffix = (suffix + probability[e] * inverse[e + 1]) % MOD;
                next[e] = suffix;
            }

            probability.swap(next);
